{"command":"cd /private/var/folders/yw/fbsfvfm95956m4m6yfd49z_c0000gn/T/tair-expanded-project-2t37swjk/workspace && node --input-type=module -e "
import { uniqueStrings } from './unique_base.mjs';

// Basic dedup preserving order
const a = ['apple', 'banana', 'apple', 'cherry', 'banana'];
const r1 = uniqueStrings(a);
console.log('r1:', JSON.stringify(r1));
console.assert(JSON.stringify(r1) === JSON.stringify(['apple','banana','cherry']), 'basic dedup failed');

// Case sensitivity
const r2 = uniqueStrings(['Apple', 'apple', 'APPLE', 'apple']);
console.log('r2:', JSON.stringify(r2));
console.assert(JSON.stringify(r2) === JSON.stringify(['Apple','apple','APPLE']), 'case sensitivity failed');

// Whitespace not trimmed
const r3 = uniqueStrings([' a ', 'a', ' a ', 'a']);
console.log('r3:', JSON.stringify(r3));
console.assert(JSON.stringify(r3) === JSON.stringify([' a ','a']), 'whitespace handling failed');

// Input not mutated
const input = ['x', 'y', 'x'];
const copy = [...input];
uniqueStrings(input);
console.assert(JSON.stringify(input) === JSON.stringify(copy), 'input mutated!');

// Empty array
const r4 = uniqueStrings([]);
console.assert(Array.isArray(r4) && r4.length === 0, 'empty array failed');

// Empty strings
const r5 = uniqueStrings(['', '', 'a', '']);
console.assert(JSON.stringify(r5) === JSON.stringify(['','a']), 'empty string dedup failed');

console.log('All checks passed.');
"
"}

